/* From Uiverse.io by ahmed150up - Tags: form */
.__UIV_SCOPE__ .card {
  width: 350px;
  border: 1px solid #ccc;
  border-radius: 4px;
  box-shadow: 2px 2px 8px rgba(0,0,0,0.1);
  overflow: hidden;
  margin: 10px;
}

.__UIV_SCOPE__ .card-header {
  background-color: #333;
  padding: 16px;
  text-align: center;
}

.__UIV_SCOPE__ .card-header .text-header {
  margin: 0;
  font-size: 18px;
  color: rgb(255, 255, 255);
}

.__UIV_SCOPE__ .card-body {
  padding: 16px;
}

.__UIV_SCOPE__ .form-group {
  margin-bottom: 10px;
}

.__UIV_SCOPE__ .form-group label {
  display: block;
  font-size: 14px;
  color: #333;
  font-weight: bold;
  margin-bottom: 1px;
}

.__UIV_SCOPE__ .form-group input[type="text"],
.__UIV_SCOPE__ .form-group input[type="email"],
.__UIV_SCOPE__ .form-group input[type="password"] {
  width: 100%;
  padding: 8px;
  font-size: 14px;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.__UIV_SCOPE__ .btn {
  padding: 12px 24px;
  margin-left: 13px;
  font-size: 16px;
  border: none;
  border-radius: 4px;
  background-color: #333;
  color: #fff;
  text-transform: uppercase;
  transition: background-color 0.2s ease-in-out;
  cursor: pointer
}

.__UIV_SCOPE__ .btn:hover {
  background-color: #ccc;
  color: #333;
}
